using Mpgsql.Types;

namespace Mpgsql.Internal;

internal static class ObjectParameterEncoding
{
    internal static MpgsqlParameterValue Create(uint oid, object value)
    {
        return value switch
        {
            DateOnly typed                              => ParameterEncoding<DateOnly>.Create(oid, typed),
            DateOnly?[] typed                           => ParameterEncoding<DateOnly?[]>.Create(oid, typed),
            DateOnly[] typed                            => ParameterEncoding<DateOnly[]>.Create(oid, typed),
            DateTime typed                              => ParameterEncoding<DateTime>.Create(oid, typed),
            DateTime?[] typed                           => ParameterEncoding<DateTime?[]>.Create(oid, typed),
            DateTimeOffset typed                        => ParameterEncoding<DateTimeOffset>.Create(oid, typed),
            DateTimeOffset?[] typed                     => ParameterEncoding<DateTimeOffset?[]>.Create(oid, typed),
            DateTimeOffset[] typed                      => ParameterEncoding<DateTimeOffset[]>.Create(oid, typed),
            DateTime[] typed                            => ParameterEncoding<DateTime[]>.Create(oid, typed),
            Guid typed                                  => ParameterEncoding<Guid>.Create(oid, typed),
            Guid?[] typed                               => ParameterEncoding<Guid?[]>.Create(oid, typed),
            Guid[] typed                                => ParameterEncoding<Guid[]>.Create(oid, typed),
            Memory<byte> typed                          => ParameterEncoding<Memory<byte>>.Create(oid, typed),
            Memory<byte>?[] typed                       => ParameterEncoding<Memory<byte>?[]>.Create(oid, typed),
            Memory<byte>[] typed                        => ParameterEncoding<Memory<byte>[]>.Create(oid, typed),
            PgDate typed                                => ParameterEncoding<PgDate>.Create(oid, typed),
            PgDate?[] typed                             => ParameterEncoding<PgDate?[]>.Create(oid, typed),
            PgDate[] typed                              => ParameterEncoding<PgDate[]>.Create(oid, typed),
            PgInet typed                                => ParameterEncoding<PgInet>.Create(oid, typed),
            PgInet?[] typed                             => ParameterEncoding<PgInet?[]>.Create(oid, typed),
            PgInet[] typed                              => ParameterEncoding<PgInet[]>.Create(oid, typed),
            PgInterval typed                            => ParameterEncoding<PgInterval>.Create(oid, typed),
            PgInterval?[] typed                         => ParameterEncoding<PgInterval?[]>.Create(oid, typed),
            PgInterval[] typed                          => ParameterEncoding<PgInterval[]>.Create(oid, typed),
            PgNumeric typed                             => ParameterEncoding<PgNumeric>.Create(oid, typed),
            PgNumeric?[] typed                          => ParameterEncoding<PgNumeric?[]>.Create(oid, typed),
            PgNumeric[] typed                           => ParameterEncoding<PgNumeric[]>.Create(oid, typed),
            PgTime typed                                => ParameterEncoding<PgTime>.Create(oid, typed),
            PgTime?[] typed                             => ParameterEncoding<PgTime?[]>.Create(oid, typed),
            PgTimeTz typed                              => ParameterEncoding<PgTimeTz>.Create(oid, typed),
            PgTimeTz?[] typed                           => ParameterEncoding<PgTimeTz?[]>.Create(oid, typed),
            PgTimeTz[] typed                            => ParameterEncoding<PgTimeTz[]>.Create(oid, typed),
            PgTime[] typed                              => ParameterEncoding<PgTime[]>.Create(oid, typed),
            PgTimestamp typed                           => ParameterEncoding<PgTimestamp>.Create(oid, typed),
            PgTimestamp?[] typed                        => ParameterEncoding<PgTimestamp?[]>.Create(oid, typed),
            PgTimestampTz typed                         => ParameterEncoding<PgTimestampTz>.Create(oid, typed),
            PgTimestampTz?[] typed                      => ParameterEncoding<PgTimestampTz?[]>.Create(oid, typed),
            PgTimestampTz[] typed                       => ParameterEncoding<PgTimestampTz[]>.Create(oid, typed),
            PgTimestamp[] typed                         => ParameterEncoding<PgTimestamp[]>.Create(oid, typed),
            ReadOnlyMemory<DateOnly> typed              => ParameterEncoding<ReadOnlyMemory<DateOnly>>.Create(oid, typed),
            ReadOnlyMemory<DateOnly?> typed             => ParameterEncoding<ReadOnlyMemory<DateOnly?>>.Create(oid, typed),
            ReadOnlyMemory<DateTime> typed              => ParameterEncoding<ReadOnlyMemory<DateTime>>.Create(oid, typed),
            ReadOnlyMemory<DateTime?> typed             => ParameterEncoding<ReadOnlyMemory<DateTime?>>.Create(oid, typed),
            ReadOnlyMemory<DateTimeOffset> typed        => ParameterEncoding<ReadOnlyMemory<DateTimeOffset>>.Create(oid, typed),
            ReadOnlyMemory<DateTimeOffset?> typed       => ParameterEncoding<ReadOnlyMemory<DateTimeOffset?>>.Create(oid, typed),
            ReadOnlyMemory<Guid> typed                  => ParameterEncoding<ReadOnlyMemory<Guid>>.Create(oid, typed),
            ReadOnlyMemory<Guid?> typed                 => ParameterEncoding<ReadOnlyMemory<Guid?>>.Create(oid, typed),
            ReadOnlyMemory<Memory<byte>> typed          => ParameterEncoding<ReadOnlyMemory<Memory<byte>>>.Create(oid, typed),
            ReadOnlyMemory<Memory<byte>?> typed         => ParameterEncoding<ReadOnlyMemory<Memory<byte>?>>.Create(oid, typed),
            ReadOnlyMemory<PgDate> typed                => ParameterEncoding<ReadOnlyMemory<PgDate>>.Create(oid, typed),
            ReadOnlyMemory<PgDate?> typed               => ParameterEncoding<ReadOnlyMemory<PgDate?>>.Create(oid, typed),
            ReadOnlyMemory<PgInet> typed                => ParameterEncoding<ReadOnlyMemory<PgInet>>.Create(oid, typed),
            ReadOnlyMemory<PgInet?> typed               => ParameterEncoding<ReadOnlyMemory<PgInet?>>.Create(oid, typed),
            ReadOnlyMemory<PgInterval> typed            => ParameterEncoding<ReadOnlyMemory<PgInterval>>.Create(oid, typed),
            ReadOnlyMemory<PgInterval?> typed           => ParameterEncoding<ReadOnlyMemory<PgInterval?>>.Create(oid, typed),
            ReadOnlyMemory<PgNumeric> typed             => ParameterEncoding<ReadOnlyMemory<PgNumeric>>.Create(oid, typed),
            ReadOnlyMemory<PgNumeric?> typed            => ParameterEncoding<ReadOnlyMemory<PgNumeric?>>.Create(oid, typed),
            ReadOnlyMemory<PgTime> typed                => ParameterEncoding<ReadOnlyMemory<PgTime>>.Create(oid, typed),
            ReadOnlyMemory<PgTime?> typed               => ParameterEncoding<ReadOnlyMemory<PgTime?>>.Create(oid, typed),
            ReadOnlyMemory<PgTimeTz> typed              => ParameterEncoding<ReadOnlyMemory<PgTimeTz>>.Create(oid, typed),
            ReadOnlyMemory<PgTimeTz?> typed             => ParameterEncoding<ReadOnlyMemory<PgTimeTz?>>.Create(oid, typed),
            ReadOnlyMemory<PgTimestamp> typed           => ParameterEncoding<ReadOnlyMemory<PgTimestamp>>.Create(oid, typed),
            ReadOnlyMemory<PgTimestamp?> typed          => ParameterEncoding<ReadOnlyMemory<PgTimestamp?>>.Create(oid, typed),
            ReadOnlyMemory<PgTimestampTz> typed         => ParameterEncoding<ReadOnlyMemory<PgTimestampTz>>.Create(oid, typed),
            ReadOnlyMemory<PgTimestampTz?> typed        => ParameterEncoding<ReadOnlyMemory<PgTimestampTz?>>.Create(oid, typed),
            ReadOnlyMemory<ReadOnlyMemory<byte>> typed  => ParameterEncoding<ReadOnlyMemory<ReadOnlyMemory<byte>>>.Create(oid, typed),
            ReadOnlyMemory<ReadOnlyMemory<byte>?> typed => ParameterEncoding<ReadOnlyMemory<ReadOnlyMemory<byte>?>>.Create(oid, typed),
            ReadOnlyMemory<TimeOnly> typed              => ParameterEncoding<ReadOnlyMemory<TimeOnly>>.Create(oid, typed),
            ReadOnlyMemory<TimeOnly?> typed             => ParameterEncoding<ReadOnlyMemory<TimeOnly?>>.Create(oid, typed),
            ReadOnlyMemory<TimeSpan> typed              => ParameterEncoding<ReadOnlyMemory<TimeSpan>>.Create(oid, typed),
            ReadOnlyMemory<TimeSpan?> typed             => ParameterEncoding<ReadOnlyMemory<TimeSpan?>>.Create(oid, typed),
            ReadOnlyMemory<bool> typed                  => ParameterEncoding<ReadOnlyMemory<bool>>.Create(oid, typed),
            ReadOnlyMemory<bool?> typed                 => ParameterEncoding<ReadOnlyMemory<bool?>>.Create(oid, typed),
            ReadOnlyMemory<byte> typed                  => ParameterEncoding<ReadOnlyMemory<byte>>.Create(oid, typed),
            ReadOnlyMemory<byte>?[] typed               => ParameterEncoding<ReadOnlyMemory<byte>?[]>.Create(oid, typed),
            ReadOnlyMemory<byte>[] typed                => ParameterEncoding<ReadOnlyMemory<byte>[]>.Create(oid, typed),
            ReadOnlyMemory<byte[]?> typed               => ParameterEncoding<ReadOnlyMemory<byte[]?>>.Create(oid, typed),
            ReadOnlyMemory<decimal> typed               => ParameterEncoding<ReadOnlyMemory<decimal>>.Create(oid, typed),
            ReadOnlyMemory<decimal?> typed              => ParameterEncoding<ReadOnlyMemory<decimal?>>.Create(oid, typed),
            ReadOnlyMemory<double> typed                => ParameterEncoding<ReadOnlyMemory<double>>.Create(oid, typed),
            ReadOnlyMemory<double?> typed               => ParameterEncoding<ReadOnlyMemory<double?>>.Create(oid, typed),
            ReadOnlyMemory<float> typed                 => ParameterEncoding<ReadOnlyMemory<float>>.Create(oid, typed),
            ReadOnlyMemory<float?> typed                => ParameterEncoding<ReadOnlyMemory<float?>>.Create(oid, typed),
            ReadOnlyMemory<int> typed                   => ParameterEncoding<ReadOnlyMemory<int>>.Create(oid, typed),
            ReadOnlyMemory<int?> typed                  => ParameterEncoding<ReadOnlyMemory<int?>>.Create(oid, typed),
            ReadOnlyMemory<long> typed                  => ParameterEncoding<ReadOnlyMemory<long>>.Create(oid, typed),
            ReadOnlyMemory<long?> typed                 => ParameterEncoding<ReadOnlyMemory<long?>>.Create(oid, typed),
            ReadOnlyMemory<short> typed                 => ParameterEncoding<ReadOnlyMemory<short>>.Create(oid, typed),
            ReadOnlyMemory<short?> typed                => ParameterEncoding<ReadOnlyMemory<short?>>.Create(oid, typed),
            ReadOnlyMemory<string?> typed               => ParameterEncoding<ReadOnlyMemory<string?>>.Create(oid, typed),
            ReadOnlyMemory<uint> typed                  => ParameterEncoding<ReadOnlyMemory<uint>>.Create(oid, typed),
            ReadOnlyMemory<uint?> typed                 => ParameterEncoding<ReadOnlyMemory<uint?>>.Create(oid, typed),
            TimeOnly typed                              => ParameterEncoding<TimeOnly>.Create(oid, typed),
            TimeOnly?[] typed                           => ParameterEncoding<TimeOnly?[]>.Create(oid, typed),
            TimeOnly[] typed                            => ParameterEncoding<TimeOnly[]>.Create(oid, typed),
            TimeSpan typed                              => ParameterEncoding<TimeSpan>.Create(oid, typed),
            TimeSpan?[] typed                           => ParameterEncoding<TimeSpan?[]>.Create(oid, typed),
            TimeSpan[] typed                            => ParameterEncoding<TimeSpan[]>.Create(oid, typed),
            bool typed                                  => ParameterEncoding<bool>.Create(oid, typed),
            bool?[] typed                               => ParameterEncoding<bool?[]>.Create(oid, typed),
            bool[] typed                                => ParameterEncoding<bool[]>.Create(oid, typed),
            byte[] typed                                => ParameterEncoding<byte[]>.Create(oid, typed),
            byte[]?[] typed                             => ParameterEncoding<byte[]?[]>.Create(oid, typed),
            decimal typed                               => ParameterEncoding<decimal>.Create(oid, typed),
            decimal?[] typed                            => ParameterEncoding<decimal?[]>.Create(oid, typed),
            decimal[] typed                             => ParameterEncoding<decimal[]>.Create(oid, typed),
            double typed                                => ParameterEncoding<double>.Create(oid, typed),
            double?[] typed                             => ParameterEncoding<double?[]>.Create(oid, typed),
            double[] typed                              => ParameterEncoding<double[]>.Create(oid, typed),
            float typed                                 => ParameterEncoding<float>.Create(oid, typed),
            float?[] typed                              => ParameterEncoding<float?[]>.Create(oid, typed),
            float[] typed                               => ParameterEncoding<float[]>.Create(oid, typed),
            int typed                                   => ParameterEncoding<int>.Create(oid, typed),
            int?[] typed                                => ParameterEncoding<int?[]>.Create(oid, typed),
            int[] typed                                 => ParameterEncoding<int[]>.Create(oid, typed),
            long typed                                  => ParameterEncoding<long>.Create(oid, typed),
            long?[] typed                               => ParameterEncoding<long?[]>.Create(oid, typed),
            long[] typed                                => ParameterEncoding<long[]>.Create(oid, typed),
            short typed                                 => ParameterEncoding<short>.Create(oid, typed),
            short?[] typed                              => ParameterEncoding<short?[]>.Create(oid, typed),
            short[] typed                               => ParameterEncoding<short[]>.Create(oid, typed),
            string typed                                => ParameterEncoding<string>.Create(oid, typed),
            string?[] typed                             => ParameterEncoding<string?[]>.Create(oid, typed),
            uint typed                                  => ParameterEncoding<uint>.Create(oid, typed),
            uint?[] typed                               => ParameterEncoding<uint?[]>.Create(oid, typed),
            uint[] typed                                => ParameterEncoding<uint[]>.Create(oid, typed),
            _                                           => throw new InvalidCastException($"Unsupported parameter CLR type {value.GetType()}.")
        };
    }
}